print('ROOT KEYS',list(x))
for k,v in x.items():
 if k"'!='"'context': print(k,json.dumps(v,indent=2))
c=x.get('context',{})
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge','retrieval']: print(k,json.dumps(v,indent=2)[:22000])
